export const SLASH_COMMANDS = [
    { name: "help", usage: "/help [command]", description: "Show command help" },
    { name: "model", usage: "/model list|use|info|pull <ref>", description: "Manage cloud and local models" },
    { name: "runtime", usage: "/runtime list|status|start|stop", description: "Manage local model runtimes" },
    { name: "provider", usage: "/provider list|use|add", description: "Manage remote provider profiles" },
    { name: "mode", usage: "/mode read-only|balanced|autonomous", description: "Set tool autonomy for this configuration" },
    { name: "route", usage: "/route manual|auto|local|cloud", description: "Configure model routing" },
    { name: "offline", usage: "/offline on|off", description: "Block or allow all external network access" },
    { name: "workspace", usage: "/workspace [path]", description: "Show or change the approved workspace" },
    { name: "instructions", usage: "/instructions", description: "Show loaded project instruction files" },
    { name: "tree", usage: "/tree [glob]", description: "Show an ignore-aware project tree" },
    { name: "index", usage: "/index status", description: "Show detected project metadata" },
    { name: "context", usage: "/context list|add|drop|clear", description: "Manage pinned model context" },
    { name: "diff", usage: "/diff", description: "Show the current Git diff" },
    { name: "git", usage: "/git status|diff|log", description: "Run safe read-only Git inspection" },
    { name: "test", usage: "/test [script]", description: "Run an npm test script after approval" },
    { name: "build", usage: "/build", description: "Run the detected build after approval" },
    { name: "review", usage: "/review [focus]", description: "Ask Forge to review current changes" },
    { name: "plan", usage: "/plan <goal>", description: "Ask Forge for an implementation plan" },
    { name: "fix", usage: "/fix <problem>", description: "Ask Forge to diagnose and fix a problem" },
    { name: "tools", usage: "/tools", description: "List tools and risk levels" },
    { name: "doctor", usage: "/doctor", description: "Diagnose configuration and runtimes" },
    { name: "status", usage: "/status", description: "Show active model, routing, and permission status" },
    { name: "ui", usage: "/ui inline|tui", description: "Choose the terminal interface" },
    { name: "new", aliases: ["clear"], usage: "/new", description: "Start a fresh conversation" },
    { name: "history", usage: "/history", description: "Show conversation history" },
    { name: "save", usage: "/save [name]", description: "Save the current session" },
    { name: "checkpoint", usage: "/checkpoint [name]", description: "Save a recovery checkpoint" },
    { name: "load", usage: "/load <name>", description: "Load a session" },
    { name: "sessions", usage: "/sessions", description: "List saved sessions" },
    { name: "cost", usage: "/cost", description: "Show token usage and estimated cost" },
    { name: "limit", usage: "/limit show|set|clear", description: "Show or configure usage-plan limits" },
    { name: "theme", usage: "/theme", description: "Cycle the terminal theme" },
    { name: "exit", aliases: ["quit"], usage: "/exit", description: "Quit Forge" },
];
export function slashCommandNames() {
    return SLASH_COMMANDS.flatMap((command) => [command.name, ...(command.aliases ?? [])]);
}
